    { key: "execBriefTerms", storeName: "exec_brief_terms",  manifestId: "__data_exec_brief_terms",          filename: "exec_brief_terms.json", label: "Exec Brief Terms",            confidential: false },
    { key: "emailTemplates", storeName: "email_templates",   manifestId: "__data_email_templates",           filename: "email_templates.json",  label: "Email Templates",             confidential: false },
    { key: "cleanerRules",   storeName: "cleaner_rules",     manifestId: "__data_cleaner_rules",             filename: "cleaner_rules.json",    label: "Cleaner Rules",               confidential: false },
